package com.minewaku.chatter.identityaccess.presentation.user;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import com.minewaku.chatter.identityaccess.user.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { private final RegisterUserUseCase register; public AuthController(RegisterUserUseCase r){register=r;} @PostMapping("/register") public ResponseEntity<Void> register(@Valid @RequestBody RegisterRequest r){RegisterUserUseCase.Result result=register.handle(new RegisterUserUseCase.Command(r.email(),r.username(),r.birthday(),r.password()));return result instanceof RegisterUserUseCase.AccountAlreadyExists?ResponseEntity.status(HttpStatus.CONFLICT).build():ResponseEntity.ok().build();} }